class Solution {
    public String smallestNumber(long n) {
        if (n == 1) return "1";
        StringBuilder sb = new StringBuilder();
        for (int d = 9; d >= 2; d--) {
            while (n % d == 0) {
                sb.append(d);
                n /= d;
            }
        }
        if (n > 1) return "-1";
        return sb.reverse().toString();
    }
}

