var smallestNumber = function(n) {
    let bn = BigInt(n);
    if (bn === 1n) return '1';
    const digits = [];
    for (let d = 9n; d >= 2n; d--) {
        while (bn % d === 0n) {
            digits.push(d.toString());
            bn /= d;
        }
    }
    if (bn > 1n) return '-1';
    digits.reverse();
    return digits.join('');
};
